
<?php require_once __DIR__ . '/auth.php'; wajibLogin(); require_once __DIR__ . '/../config.php'; $pageTitle='Dashboard Admin'; $assetPrefix='../';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['order_id'],$_POST['status'])){verifikasiAdminCsrf();$allowed=['Menunggu','Diproses','Selesai','Dibatalkan'];if(in_array($_POST['status'],$allowed,true)){$s=$pdo->prepare('UPDATE orders SET status=? WHERE id=?');$s->execute([$_POST['status'],(int)$_POST['order_id']]);}header('Location: index.php');exit;}
$orders=$pdo->query('SELECT * FROM orders ORDER BY id ASC')->fetchAll();$today=$pdo->query('SELECT COUNT(*) FROM orders WHERE DATE(created_at)=CURDATE()')->fetchColumn();$waiting=$pdo->query("SELECT COUNT(*) FROM orders WHERE status IN ('Menunggu','Diproses')")->fetchColumn();$revenue=$pdo->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE status='Selesai' AND DATE(created_at)=CURDATE()")->fetchColumn();require '../includes/header.php'; ?>
<span class="eyebrow">Panel pengelola</span><h1 class="page-title">Dashboard Admin</h1><p class="muted">Urutan tabel mengikuti FIFO: pesanan paling awal berada di bagian atas.</p><div class="stats"><div class="card stat"><span class="muted">Pesanan hari ini</span><strong><?= $today ?></strong></div><div class="card stat"><span class="muted">Dalam antrean</span><strong><?= $waiting ?></strong></div><div class="card stat"><span class="muted">Pendapatan selesai hari ini</span><strong style="font-size:23px"><?= rupiah($revenue) ?></strong></div></div><div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:18px"><a class="btn" href="qr.php">Buat / Lihat QR Code</a><a class="btn light" href="menu.php">Kelola Menu</a><a class="btn light" href="../order.php">Buka Halaman Pesan</a><form method="post" action="logout.php" style="margin-left:auto"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(adminCsrfToken(), ENT_QUOTES, 'UTF-8') ?>"><button class="btn light" type="submit">Logout (<?= htmlspecialchars($_SESSION['admin_username'] ?? 'Admin', ENT_QUOTES, 'UTF-8') ?>)</button></form></div>
<div class="table-wrap"><table><thead><tr><th>Antrean</th><th>Waktu</th><th>Pelanggan</th><th>Jenis</th><th>Total</th><th>Status</th><th>Ubah Status</th></tr></thead><tbody><?php if(!$orders): ?><tr><td colspan="7">Belum ada pesanan.</td></tr><?php endif; ?><?php foreach($orders as $o): ?><tr><td><strong>A<?= str_pad((string)$o['queue_no'],3,'0',STR_PAD_LEFT) ?></strong><div class="small muted">Order #<?= $o['id'] ?></div></td><td><?= date('d/m H:i',strtotime($o['created_at'])) ?></td><td><?= htmlspecialchars($o['customer_name']) ?></td><td><?= htmlspecialchars($o['order_type']) ?></td><td><?= rupiah($o['total']) ?></td><td><span class="status <?= strtolower($o['status']) ?>"><?= $o['status'] ?></span></td><td><form method="post" class="admin-actions"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(adminCsrfToken(), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="order_id" value="<?= $o['id'] ?>"><select name="status"><?php foreach(['Menunggu','Diproses','Selesai','Dibatalkan'] as $s): ?><option <?= $o['status']===$s?'selected':'' ?>><?= $s ?></option><?php endforeach; ?></select><button class="btn" type="submit">Simpan</button></form></td></tr><?php endforeach; ?></tbody></table></div>
